#!/usr/bin/env python3
"""Render DejaVu Sans Mono Bold (ASCII 32-126) into ESP32P4/main/font.h.

Each glyph is FONT_H rows of uint16_t, bit (FONT_W - 1 - x) set for a lit
pixel at column x. Run again only to change the font or its size.
"""
import os
from PIL import Image, ImageDraw, ImageFont

TTF = "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf"
SIZE = 16
W, H = 10, 19
OUT = os.path.join(os.path.dirname(__file__), "../ESP32P4/main/font.h")

font = ImageFont.truetype(TTF, SIZE)
lines = [
    "#pragma once",
    "/* Generated by tools/gen_font.py: DejaVu Sans Mono Bold %dpx, ASCII 32-126. */" % SIZE,
    "#include <stdint.h>",
    "",
    "#define FONT_W %d" % W,
    "#define FONT_H %d" % H,
    "",
    "static const uint16_t FONT[95][FONT_H] = {",
]
for c in range(32, 127):
    img = Image.new("1", (W, H), 0)
    ImageDraw.Draw(img).text((0, 0), chr(c), font=font, fill=1)
    rows = []
    for y in range(H):
        bits = 0
        for x in range(W):
            if img.getpixel((x, y)):
                bits |= 1 << (W - 1 - x)
        rows.append("0x%03x" % bits)
    lines.append("    {%s}, /* %r */" % (", ".join(rows), chr(c)))
lines.append("};")

with open(OUT, "w") as f:
    f.write("\n".join(lines) + "\n")
